import * as dotenv from 'dotenv';
import * as path from 'path';
import { PrismaClient } from '@prisma/client';

// Загружаем переменные окружения
const projectRoot = process.cwd();
dotenv.config({ path: path.join(projectRoot, `.env.development.local`) });
dotenv.config({ path: path.join(projectRoot, '.env.local') });
dotenv.config({ path: path.join(projectRoot, '.env') });

const prisma = new PrismaClient();

async function checkMigrations() {
  try {
    const migrations = await prisma._prismaAdmin._querRawUnsafe('SELECT * FROM "_prisma_migrations"');
    console.log('✅ Миграции в БД:', JSON.stringify(migrations, null, 2));
  } catch (e: any) {
    console.log('❌ Ошибка при чтении миграций:', e.message);
  } finally {
    await prisma.$disconnect();
  }
}

checkMigrations();

import type { Metadata } from 'next';
import { Geist, Geist_Mono, Inter } from 'next/font/google';

import '@workspace/ui/globals.css';
import { ThemeProvider } from '@/components/theme-provider';
import { AuthProvider } from '@/components/auth/auth-context';
import { Toaster } from '@workspace/ui/components/sonner';
import { cn } from '@workspace/ui/lib/utils';

const inter = Inter({
  subsets: ['latin'],
  variable: '--font-sans',
});

const geist = Geist({
  subsets: ['latin'],
  variable: '--font-geist',
});

const fontMono = Geist_Mono({
  subsets: ['latin'],
  variable: '--font-mono',
});

export const metadata: Metadata = {
  title: {
    default: 'Library',
    template: '%s · Library',
  },
  description: 'Базовая обёртка проекта с авторизацией и типизированными формами.',
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html
      lang="ru"
      suppressHydrationWarning
      className={cn(
        'antialiased',
        geist.variable,
        fontMono.variable,
        inter.variable,
      )}
    >
      <body>
        <ThemeProvider>
          <AuthProvider>
            {children}
            <Toaster richColors position="top-right" />
          </AuthProvider>
        </ThemeProvider>
      </body>
    </html>
  );
}

